const F = CARESUITE_SOFTWARE_FACTS;
const provider = `${F.provider}, ${F.legalForm}, Inhaber ${F.owner}, ${F.address}. Kontakt: ${F.email}. Website: ${F.website}.`;
const system = 'CareSuite HealthOS als Webanwendung und mobile App mit Verwaltungs-, Mitarbeiter- und Klientenportal. Die verfügbaren Funktionen richten sich nach der verwendeten Edition, den aktivierten Funktionen und den persönlichen Berechtigungen.';
const roles = 'Die nutzende Organisation entscheidet über Zweck, Rechtsgrundlage, fachlichen Inhalt, Aufbewahrung und Zugriffsrechte ihrer Klienten-, Personal- und Leistungsdaten. Sie ist dafür Verantwortlicher. CareSuite verarbeitet diese Daten im Rahmen einer wirksamen Vereinbarung über Auftragsverarbeitung nach dokumentierter Weisung. Für eigene Website-, Konto-, Vertrags-, Support- und Sicherheitszwecke ist CareSuite selbst Verantwortlicher.';
const data = 'Verarbeitet werden je nach Aufgabe Namen, Anschriften, Kontaktdaten, interne Personen- und Mandantenkennungen, Rollen, Versicherungs- und Kostenträgerangaben, Versorgungs- und Gesundheitsdaten, Beschäftigungs- und Qualifikationsdaten, Termine, Dienste, Einsätze, Arbeits- und Leistungszeiten, Berichte, Nachrichten, Fotos, Dateien, Leistungsbestätigungen sowie technische Sitzungs- und Sicherheitsdaten. Dienstliche Standortdaten kommen nur bei genutzten Standortfunktionen hinzu.';
const access = 'Verwaltungszugänge dürfen nur für ausdrücklich zugewiesene Verwaltungsaufgaben verwendet werden. Mitarbeitende bearbeiten ihre freigegebenen Einsätze und Fachdaten; ein Mitarbeiterportal ist keine allgemeine Freigabe sämtlicher Personalakten. Klientenzugänge betreffen die eigene zugeordnete Person und freigegebene Inhalte. Vertretungsbefugnisse müssen nachgewiesen sein. Die Rolle allein ersetzt weder eine fachliche Zuständigkeit noch eine Datenfreigabe.';
const gps = 'Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen.';
const optional = 'Karten und Routen können Google Maps verwenden. Push-Mitteilungen können Expo Push verwenden. Google Workspace und weitere Schnittstellen werden nur nach organisatorischer Freigabe und tatsächlicher Verbindung genutzt. KI- und Sprachfunktionen können OpenAI, Dokumentenanalyse gegebenenfalls Azure Document Intelligence verwenden. Die technische Vorbereitung einer Schnittstelle ist keine Aktivierung und keine pauschale Erlaubnis, personenbezogene Daten zu übermitteln.';
const security = 'Im Code vorgesehen sind persönliche Authentifizierung, Mandanten- und Rollenbezug, HTTPS-Übertragung, Datenbankregeln und geschützte Dateizugriffe. Die Organisation vergibt die geringsten erforderlichen Rechte und prüft sie bei Rollenwechsel und Austritt. Technische Mechanismen, Datensicherung, Wiederherstellung, Supportzugriffe und Löschläufe sind vor Betriebsfreigabe mit realen Nachweisen zu prüfen. Dieser Entwurf bescheinigt keine bestandene Sicherheitsprüfung.';
const rights = 'Betroffene Personen können Auskunft, Berichtigung, Löschung, Einschränkung und, soweit anwendbar, Datenübertragbarkeit verlangen. Eine freiwillige Einwilligung kann für die Zukunft widerrufen werden. Bei einer Verarbeitung aufgrund berechtigter Interessen besteht unter den gesetzlichen Voraussetzungen ein Widerspruchsrecht. Beschwerden sind bei einer zuständigen Datenschutzaufsichtsbehörde möglich. Die zuständige Organisation beantwortet Anträge grundsätzlich innerhalb eines Monats; eine gesetzlich zulässige Verlängerung wird begründet mitgeteilt.';
const signatures = 'Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet.';
const retention = 'Für Pflege-, Personal-, Leistungs-, Vertrags- und Falldaten legt die verantwortliche Organisation zweckbezogene Fristen mit Rechtsgrundlage, Fristbeginn und Lösch- oder Sperrverfahren fest. Der Verlust einer Benutzerberechtigung löscht keine aufbewahrungspflichtige Akte. Löschung, Export und Vertragsende sind gesonderte Vorgänge. Dauer von Sicherungskopien und technische Durchführung sind mit dem Betriebsnachweis abzugleichen; eine pauschale Frist für alle Daten ist nicht vorgesehen.';
const incident = 'Verlust eines Geräts, fremder Kontozugriff, Fehlversand, unzulässige Freigabe und vermutete Offenlegung werden unverzüglich intern gemeldet. Zugänge oder betroffene Freigaben werden soweit erforderlich gesperrt, Nachweise gesichert und Umfang sowie Risiko dokumentiert. Der Auftragsverarbeiter informiert den Verantwortlichen unverzüglich. Der Verantwortliche prüft die Meldung an die Aufsichtsbehörde möglichst binnen 72 Stunden ab Kenntnis und die unverzügliche Information Betroffener bei hohem Risiko. Gründe für eine unterlassene Meldung werden ebenfalls dokumentiert.';
const section = (key: string, heading: string, text: string): CentralDocumentSection => ({key, heading, text});
const S = (...rows: [string, string][]) => rows.map(([heading,text],i)=>section(`cs_${i+1}`,heading,text));
const field = (key: string, label: string, defaultValue?: string, required = false): CentralDocumentField => ({key:`cs_${key}`,label,type:'multiline',required,...(defaultValue ? {defaultValue} : {})});
type Content = { sections: CentralDocumentSection[]; fields?: CentralDocumentField[]; layout?: 'contract' | 'form'; target?: 'company' | 'employee' | 'client' };
const operational = (purpose: string, ...specific: CentralDocumentField[]) => [field('system','System und Anwendungsbereich',`CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: ${purpose}.`),...specific];
const privacy: Record<string, Content> = {
  '001': {fields:operational('Verzeichnis des CareSuite-Verfahrens',field('controller','Verantwortliche Organisation und Datenschutzkontakt',undefined,true),field('legal_basis','Konkrete Rechtsgrundlagen je Verarbeitungszweck',undefined,true),field('retention','Freigegebene Fristen und zugehörige Nachweise',undefined,true)),sections:S(
    ['Verfahren und Verantwortlichkeit',roles],
    ['Betroffene Personen und Daten','Betroffen sind registrierte Nutzer, Beschäftigte, Bewerber, Klienten, Patienten, Bewohner, Angehörige, Bevollmächtigte, gesetzliche Vertretungen und Geschäftskontakte. '+data],
    ['Zwecke und Verarbeitungsschritte','Die Organisation verwendet die Software für Aufnahme, Verwaltung, Dienst- und Einsatzplanung, fachliche Dokumentation, Kommunikation, Leistungsnachweis und Abrechnung. Daten werden eingegeben oder aus freigegebenen Beständen übernommen, berechtigten Personen angezeigt, geändert, zu Nachweisen zusammengestellt und nach dem jeweiligen Löschkonzept archiviert oder gelöscht. Optionale Standort- und KI-Verfahren erhalten einen eigenen Verfahrenseintrag.'],
    ['Empfänger und Übermittlungen',`${provider} Supabase wird für Authentifizierung, Datenbank, Storage und serverseitige Funktionen eingesetzt; das zugeordnete Produktionsprojekt liegt in ${F.productionDatabaseRegion}. Webauslieferung kann über Vercel erfolgen. ${optional} Ein Datenbankstandort in Deutschland schließt internationale Anbieterprozesse nicht aus. Aktive Empfänger, Vertragsgrundlage und Übermittlungsmechanismus werden in der Dienstleisterliste nachgewiesen.`],
    ['Zugriff und Schutz',access+' '+security],
    ['Fristen und Fortschreibung',retention+' Änderungen an Funktionen, Empfängern, Zwecken und Rechten werden vor Nutzung bewertet und in diesem Eintrag mit Datum und verantwortlicher Person fortgeschrieben. Der Verfahrenseintrag wird mit den Informationen nach Art. 13 und 14 DSGVO abgeglichen.'])},
  '002': {fields:operational('TOM für die CareSuite-Nutzung',field('responsible','Verantwortliche Person und Prüftermin',undefined,true),field('evidence','Nachweise und abweichende Maßnahmen',undefined,true)),sections:S(
    ['Schutzziele und Geltung','Dieses Dokument beschreibt die Maßnahmen für Vertraulichkeit, Integrität, Verfügbarkeit und Wiederherstellbarkeit von CareSuite-Daten. Technisch belegte Produktmechanismen und betriebliche Maßnahmen der Organisation werden getrennt geprüft. Besonders schutzbedürftig sind Gesundheitsdaten, Personalakten, Standortverläufe und personenbezogene Nachweise.'],
    ['Zugang und Berechtigungen',access+' Persönliche Konten, kontrollierte Erstfreigabe, sichere Kennwörter, Gerätesperre und zeitnaher Rechteentzug sind verbindliche organisatorische Maßnahmen. Gemeinsame Konten und die Weitergabe von Sitzungen sind unzulässig.'],
    ['Übertragung und Datentrennung',security+' Ausdrucke, heruntergeladene PDFs und Word-Dateien unterliegen außerhalb der Plattform dem Zugriffsschutz der Organisation. E-Mail- und Cloudablagen dürfen sensible Akten nur über freigegebene sichere Verfahren aufnehmen.'],
    ['Endgeräte und Datenminimierung','Mobile Geräte werden mit Sperre, aktuellen Sicherheitsupdates und kontrollierten App-Berechtigungen betrieben. Kameras, Dateien, Mikrofon und Standort werden ausschließlich für die konkrete freigegebene Aufgabe genutzt. Lokale Kopien und Warteschlangen sind bei Gerätewechsel und Verlust zu berücksichtigen; die App wird nicht als allgemeine Geräteverwaltungs- oder Fernlöschlösung zugesichert.'],
    ['Nachweis und Wiederherstellung','Verantwortliche prüfen Sicherungsumfang, Sicherungsintervall, Aufbewahrung, getrennte Zugriffsrechte und einen tatsächlichen Wiederherstellungstest. Exportdateien, Originale und Datenbankeinträge müssen gemeinsam berücksichtigt werden. Ein eingetragener Sollwert ersetzt keinen erfolgreichen Test. Abweichungen werden mit Maßnahme, Termin und Verantwortlichem dokumentiert.'],
    ['Vorfall und Überprüfung',incident+' Maßnahmen werden bei wesentlichen Änderungen und regelmäßig risikobezogen überprüft.'])},
  '003': {fields:operational('Rollen- und Berechtigungskonzept',field('owners','Rollenverantwortliche und Freigabestelle',undefined,true),field('matrix','Personenbezogene Rechte und Aktenzuordnungen',undefined,true)),sections:S(
    ['Mandant und Personenbezug',roles+' Jede Freigabe bezieht sich auf eine bestimmte Organisation, Aufgabe und gegebenenfalls eine bestimmte Personenakte.'],
    ['Verwaltung', 'Die Verwaltung bearbeitet freigegebene Organisations-, Klienten-, Personal-, Planungs-, Dokumentations- und Abrechnungsaufgaben. Personalverwaltung, sensible Klientendaten und Rechteverwaltung erfordern jeweils eine passende Berechtigung. Ein Verwaltungszugang berechtigt nicht automatisch zu sämtlichen Gesundheits- und Beschäftigtendaten.'],
    ['Mitarbeiterportal und Klientenportal',access],
    ['Freigabe und Entzug','Einrichtende Personen prüfen Identität, Auftrag, Qualifikation und Zuordnung. Rechte werden personengebunden freigegeben, bei Vertretung zeitlich begrenzt und bei Wechsel oder Austritt entzogen. Administrations- und Supportrechte werden gesondert dokumentiert. Eine Zugangsfreigabe setzt keine Datenschutz-Einwilligung für jede betriebliche Verarbeitung voraus.'],
    ['Kontrolle','Die Organisation vergleicht aktive Konten mit Beschäftigungs- und Vertretungsstatus. Export-, Druck-, Freigabe- und Änderungsbefugnisse werden gesondert betrachtet. Fehlzuordnungen werden unverzüglich korrigiert und auf eine mögliche Datenschutzverletzung geprüft.'])},
  '004': {layout:'contract',fields:operational('Auftragsverarbeitung für die Nutzung von CareSuite HealthOS',field('processor','Auftragsverarbeiter',provider),field('instructions','Weisungsberechtigte Personen des Auftraggebers',undefined,true),field('annexes','Freigegebene TOM und aktive Unterauftragnehmer mit Stand',undefined,true)),sections:S(
    ['§ 1 Parteien Gegenstand und Dauer',`Auftraggeber ist die im Dokumentkopf bezeichnete nutzende Organisation. Auftragsverarbeiter ist ${provider} Gegenstand ist die technische Verarbeitung der vom Auftraggeber in CareSuite HealthOS eingegebenen oder rechtmäßig eingebundenen personenbezogenen Daten für den vereinbarten Plattformbetrieb. Die Verarbeitung beginnt erst auf wirksamer vertraglicher Grundlage und dauert bis zum Abschluss der angeordneten Rückgabe oder Löschung nach Vertragsende.`],
    ['§ 2 Art Zweck Daten und betroffene Personen',system+' '+data+' Betroffene sind insbesondere Beschäftigte, Nutzer, Klienten, Patienten, Bewohner, deren Kontakt- und Vertretungspersonen sowie Geschäftspartner. Tätigkeiten umfassen Erfassung, Speicherung, Bereitstellung, Übertragung, strukturierte Ausgabe, Berichtigung, Sicherung und angeordnete Löschung. Umfang und optionale Funktionen bestimmt der Auftraggeber.'],
    ['§ 3 Verantwortung und dokumentierte Weisungen','Der Auftraggeber bestimmt rechtmäßige Zwecke und Rechtsgrundlagen, erteilt nachvollziehbare Weisungen und erfüllt Informationspflichten. CareSuite verarbeitet Auftragsdaten ausschließlich danach, einschließlich Weisungen zu Drittlandübermittlungen. Gesetzlich zwingende abweichende Verarbeitungen werden vorab mitgeteilt, soweit das Gesetz eine Mitteilung erlaubt. Hält CareSuite eine Weisung für datenschutzwidrig, informiert CareSuite den Auftraggeber unverzüglich und klärt die weitere Bearbeitung. Weisungen, Änderungen und ausführende Personen werden dokumentiert.'],
    ['§ 4 Vertraulichkeit und technische Maßnahmen','Zugriffsberechtigte Personen werden zur Vertraulichkeit verpflichtet oder unterliegen einer angemessenen gesetzlichen Verschwiegenheitspflicht. CareSuite und Auftraggeber vereinbaren die in der freigegebenen TOM-Anlage bezeichneten Maßnahmen nach Art. 32 DSGVO. Änderungen dürfen das vereinbarte Schutzniveau nicht absenken; wesentliche Änderungen werden dokumentiert. Die Vertraulichkeit gilt nach Ende des Auftrags fort.'],
    ['§ 5 Unterauftragsverarbeitung','Die zum Vertrag gehörende Liste benennt die tatsächlich eingesetzten Unterauftragsverarbeiter, Leistungen, Datenkategorien und Übermittlungsmechanismen. Weitere Unterauftragsverarbeiter bedürfen der vorherigen gesonderten oder allgemeinen schriftlichen Genehmigung. Bei allgemeiner Genehmigung informiert CareSuite vor einer beabsichtigten Hinzuziehung oder Ersetzung so rechtzeitig, dass der Auftraggeber einen begründeten datenschutzbezogenen Einspruch erheben kann. Ist keine tragfähige Lösung möglich, bleibt die betroffene Verarbeitung ausgesetzt oder wird nach Vereinbarung beendet. Dieselben Datenschutzpflichten werden den Unterauftragsverarbeitern auferlegt.'],
    ['§ 6 Orte und internationale Übermittlungen',`Das zugeordnete Supabase-Produktionsprojekt befindet sich in ${F.productionDatabaseRegion}. Weitere Verarbeitungsorte, Support- und Unterauftragnehmerprozesse sind gesondert in der Anlage nachzuweisen. Übermittlungen außerhalb des EWR erfolgen nur auf dokumentierter Grundlage unter Beachtung von Kapitel V DSGVO. Ein Anbietername oder EU-Datenbankstandort ersetzt keinen Nachweis über sämtliche Verarbeitungsschritte.`],
    ['§ 7 Unterstützung bei Betroffenenrechten','CareSuite unterstützt den Auftraggeber entsprechend Art und Umfang der Verarbeitung bei Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch. Direkt bei CareSuite eingehende Anfragen zu Auftragsdaten werden ohne vermeidbare Verzögerung an den Auftraggeber weitergegeben. Eine eigenständige inhaltliche Entscheidung über Auftragsdaten erfolgt nur nach Weisung oder gesetzlicher Pflicht.'],
    ['§ 8 Vorfälle und Risikoprüfung','CareSuite meldet dem Auftraggeber bekannt gewordene Verletzungen des Schutzes der Auftragsdaten unverzüglich und stellt verfügbare Angaben zu Art, Umfang, betroffenen Personen, Folgen, Gegenmaßnahmen und Kontaktstelle bereit. Noch fehlende Informationen werden nachgereicht. Die Unterstützung umfasst, soweit erforderlich, Pflichten zu Sicherheit, Meldung, Benachrichtigung, Folgenabschätzung und Konsultation nach Art. 32 bis 36 DSGVO. Behördenmeldungen des Auftraggebers werden durch diese Vereinbarung nicht aufgeschoben.'],
    ['§ 9 Nachweise und Kontrollen','CareSuite stellt erforderliche Informationen zum Nachweis der vereinbarten Pflichten bereit und ermöglicht Überprüfungen einschließlich geeigneter Inspektionen durch den Auftraggeber oder dessen verpflichteten Prüfer. Kontrollen berücksichtigen Betriebsabläufe und Rechte anderer Mandanten; ein akuter Vorfall wird unverzüglich behandelt. Eine allgemeine Zertifizierungsbehauptung ersetzt keine verfahrensbezogenen Nachweise.'],
    ['§ 10 Rückgabe Löschung und Vertragsende','Nach Ende der Verarbeitung gibt CareSuite personenbezogene Auftragsdaten nach Wahl und dokumentierter Weisung des Auftraggebers zurück oder löscht sie einschließlich vorhandener Kopien, soweit keine gesetzliche Speicherpflicht entgegensteht. Umfang, Format, sichere Übergabe, Sperren und Behandlung rotierender Sicherungskopien werden im Abschlussauftrag festgelegt und nachgewiesen. Die Löschung eines Benutzerkontos ist keine automatische Löschung der dazugehörigen fachlichen Akte.'],
    ['§ 11 Besondere Vereinbarungen und Rangfolge','Die unterzeichneten Anlagen enthalten konkrete TOM, aktive Unterauftragsverarbeiter und individuelle Weisungen. Bei Widersprüchen zu allgemeinen Nutzungsregeln geht diese Vereinbarung für Auftragsdaten vor. Verantwortlichkeiten und Ansprüche nach der DSGVO bleiben bestehen. Diese Vereinbarung enthält keine pauschale Freistellung von Datenschutzpflichten.'])},
  '005': {target:'employee',fields:operational('Datenschutzinformation für Beschäftigte bei CareSuite-Nutzung',field('employer','Arbeitgeber und Datenschutzkontakt',undefined,true),field('local_rules','Aktivierte Funktionen Rechtsgrundlagen und Betriebsvereinbarungen',undefined,true)),sections:S(
    ['Verantwortlicher und Ansprechpartner',roles+' Verantwortlich für Ihre Beschäftigtendaten ist der im Dokumentkopf bezeichnete Arbeitgeber. Sein Datenschutzkontakt und gegebenenfalls Datenschutzbeauftragter werden vor Aushändigung ergänzt.'],
    ['Welche Daten verwendet werden','Verarbeitet werden persönliche Konto- und Kontaktdaten, Nutzerkennung, Rollen, Tätigkeit, Qualifikation, Dienst- und Einsatzzuordnung, Arbeits- und Leistungszeiten, Aufgabenstatus, betriebliche Nachrichten und Nachweise. Die Arbeitgeberverwaltung kann weitere erforderliche Personalstammdaten verarbeiten. Die Portalnutzung öffnet anderen Mitarbeitenden nicht Ihre gesamte Personalakte. Gesundheitsdaten von Beschäftigten werden auf erforderliche, besonders geschützte Personalverfahren begrenzt.'],
    ['Zwecke und rechtliche Grundlage','Die Verarbeitung dient erforderlicher Arbeitsorganisation, Dienstplanung, Zeiterfassung, Durchführung zugewiesener Einsätze, Leistungsdokumentation, gesetzlicher Nachweisführung und sicherer Kontonutzung. Der Arbeitgeber prüft § 26 BDSG und die jeweils einschlägige Grundlage nach Art. 6 DSGVO, für besondere Daten zusätzlich Art. 9 DSGVO. Betriebs- und Dienstvereinbarungen sowie Beteiligungsrechte werden berücksichtigt. Eine Unterschrift über den Empfang dieser Information ist keine pauschale Einwilligung in Überwachung.'],
    ['Standort und mobile Berechtigungen',gps+' Der Arbeitgeber legt vor Aktivierung dienstlichen Zeitraum, Datenumfang, Zugriffsberechtigte und Löschfrist fest und prüft Erforderlichkeit sowie Mitbestimmung. Geräterecht und datenschutzrechtliche Zulässigkeit sind getrennt zu beurteilen. Kamera, Mikrofon und Dateien werden nur bei einer entsprechenden Nutzeraktion benötigt.'],
    ['Empfänger und Auftragsverarbeitung',`${provider} CareSuite ist für Arbeitgeberdaten als weisungsgebundener Auftragsverarbeiter vorgesehen. Berechtigte Führungskräfte, Personalverwaltung und Einsatzverantwortliche erhalten aufgabenbezogene Einsicht. Supabase unterstützt Konto, Datenbank und Dateien; Vercel kann die Webanwendung ausliefern. ${optional} Tatsächlich aktive Dienste, internationale Bezüge und Schutzmechanismen werden in den betrieblichen Informationen benannt.`],
    ['Speicherdauer und Rechte',retention+' '+rights],
    ['Pflichtangaben und Folgen','Für einen sicheren persönlichen Zugang und die zugewiesenen betrieblichen Aufgaben sind die dazu erforderlichen Konto-, Zuordnungs- und Nachweisdaten bereitzustellen. Darüber hinaus freiwillige Funktionen werden ausdrücklich gekennzeichnet. Eine zulässige Alternative wird organisatorisch geklärt, wenn eine einzelne Berechtigung nicht erteilt wird oder ein Endgerät ausfällt. Eine Verpflichtung zur Nutzung eines privaten Smartphones entsteht nicht allein durch diese Information.'],
    ['Auswertung und eigene Verantwortung','CareSuite liefert Informationen und Arbeitshilfen. Eine ausschließlich automatisierte Entscheidung mit erheblicher rechtlicher Wirkung wird durch diese Vorlage nicht beauftragt. Heimliche, pauschale oder zweckfremde Leistungs- und Verhaltenskontrollen sind durch die Softwarefreigabe nicht legitimiert. Eigene Konten sind zu schützen; Fehler und Vorfälle werden über die bekanntgegebenen Meldewege gemeldet.'])},
  '006': {fields:operational('Aufbewahrung und Löschung von CareSuite-Daten',field('schedule','Freigegebene Fristenmatrix mit Fristbeginn und Rechtsgrundlage',undefined,true),field('backup','Belegter Backup-Zyklus und Löschverfahren',undefined,true)),sections:S(
    ['Datenklassen und Zuständigkeit',retention],
    ['Konto und Beschäftigungsende','Bei Austritt werden persönliche Zugänge, Gerätefreigaben, Vertretungsrechte und verbundene Integrationen überprüft und entzogen. Fachliche Einträge bleiben soweit erforderlich der verantwortlichen Organisation zugeordnet. Personal-, Vertrags- und Leistungsdaten werden anhand ihrer eigenen Fristen bewertet; eine pauschale Sofortlöschung erfolgt nicht.'],
    ['Technische Betriebsmeldungen','Die vorhandene Plattforminformation benennt für die zusätzliche Betriebsübersicht eine Live-Anzeige von 90 Sekunden, Bereinigung inaktiver Seitenmeldungen nach einem Tag, verknüpfter Registrierungsverläufe nach 14 Tagen und zusammengefasster Fehlermeldungen nach 30 Tagen. Die Bereinigung wird bei weiteren Betriebsmeldungen ausgelöst. Diese Angaben betreffen ausschließlich dieses technische Verfahren; sie sind keine Aufbewahrungsfristen für Pflegeakten oder sämtliche Sicherheitsprotokolle.'],
    ['Freigabe und Ausführung','Ein Löschauftrag benennt Datenklassen, betroffene Akten, Zeiträume, Ausnahmen, prüfende Person und Ausführungsnachweis. Sperren wegen gesetzlicher Pflichten oder Rechtsstreitigkeiten werden begründet. Exporte, Geräteablagen, Ausdrucke und Sicherungskopien werden in der Durchführung berücksichtigt. Wiederherstellung darf gelöschte Daten nicht ungeprüft in den aktiven Betrieb zurückführen.'],
    ['Kontrolle','Die verantwortliche Organisation kontrolliert fristgerechte Bearbeitung, fehlerhafte Löschläufe und verbleibende Kopien. Abweichungen erhalten einen dokumentierten Folgetermin. Ein geplantes Löschverfahren wird nicht als bereits ausgeführt bestätigt.'])},
  '007': {fields:operational('Datenschutz-Folgenabschätzung für CareSuite-Verfahren',field('scope','Tatsächlich eingesetzte Funktionen Umfang und Personenzahl',undefined,true),field('decision','Bewertung Freigabe und gegebenenfalls Konsultation',undefined,true)),sections:S(
    ['Verfahrensbeschreibung',roles+' '+data],
    ['Prüfung des Erfordernisses','Die Organisation prüft vor Einführung, ob voraussichtlich ein hohes Risiko vorliegt, insbesondere bei umfangreichen Gesundheitsdaten, systematischer Standort- oder Beschäftigtenbeobachtung, besonders schutzbedürftigen Personen und Kombinationen von Verfahren. Technische Verfügbarkeit ist keine Rechtfertigung. Die Vorprüfung und eine Entscheidung gegen eine Folgenabschätzung werden begründet dokumentiert.'],
    ['Risiken für betroffene Personen','Zu prüfen sind Verwechslung von Klienten, unberechtigte Akteneinsicht, zu weite Mitarbeiterrechte, Offenlegung durch Downloads oder Push-Nachrichten, Verlust mobiler Geräte, Rückschlüsse aus Bewegungsdaten, zweckfremde Nutzung von Gesundheitsdaten, falsche KI-Ausgaben und unzureichende Löschung. Eintrittswahrscheinlichkeit, Schwere und Betroffenengruppen werden für den tatsächlichen Einsatz bewertet.'],
    ['Notwendigkeit und geeignete Maßnahmen',access+' '+security+' Standortverläufe, externe Integrationen und KI erhalten eine gesonderte Erforderlichkeitsprüfung mit einer datensparsameren Alternative.'],
    ['Restrisiko und Entscheidung','Die Organisation dokumentiert umgesetzte Maßnahmen, tatsächliche Nachweise und verbleibende Risiken. Bleibt ein hohes Risiko ohne ausreichende Abhilfe, prüft sie die vorherige Konsultation nach Art. 36 DSGVO. Die Vorlage enthält keine vorweggenommene Unbedenklichkeitsfreigabe. Änderungen und neue Funktionen lösen eine erneute Bewertung aus.'])},
  '008': {fields:operational('Bearbeitung einer Datenschutzverletzung',field('event','Kenntniszeitpunkt Ereignis betroffene Daten und Umfang',undefined,true),field('action','Maßnahmen Risikoprüfung Fristen und Entscheidung',undefined,true)),sections:S(['Melden und begrenzen',incident],['CareSuite-bezogene Prüfung','Zu prüfen sind Mandant, Benutzerkonto, Aktenzuordnung, betroffene Datei, Download oder Ausdruck, Geräteverlust, aktiver Standortkontext und verbundene externe Dienste. Zugangssperre und Rechteentzug dürfen notwendige Beweissicherung nicht vereiteln. Sensible Falldaten werden nicht unverschlüsselt an allgemeine Supportadressen gesendet.'],['Abschluss und Nachweis','Die Akte enthält Ablauf, Beteiligte, betroffene Personen, Folgen, Entscheidungen, Meldungen, Empfangsnachweise, Abhilfen und Wirksamkeitsprüfung. Eine Softwaremeldung beendet die eigene Meldeprüfung des Verantwortlichen nicht.'])},
  '009': {fields:operational('Bearbeitung von Betroffenenanfragen zu CareSuite-Daten',field('request','Anfrage Eingang betroffene Person und begehrtes Recht',undefined,true),field('identity','Identitätsprüfung Zuständigkeit Frist und Ergebnis',undefined,true)),sections:S(['Zuständigkeit und Identität',roles+' Die Identität wird mit angemessenem, datensparsamem Verfahren geprüft. Bei Vertretung wird die Befugnis nachgewiesen.'],['Umfang und Frist',rights+' Ein Auskunftsvorgang berücksichtigt strukturierte Daten, Dokumente, Nachrichten, Signaturen und rechtmäßig zugeordnete Ereignisse. Rechte anderer Personen, berufliche Geheimnisse und gesetzliche Ausnahmen werden geprüft; eine Portalansicht allein ist kein vollständiger Auskunftsnachweis.'],['Sichere Bearbeitung','Die verantwortliche Organisation koordiniert erforderliche Unterstützung von CareSuite und aktiven Dienstleistern. Ausgabe und Übertragung erfolgen über einen freigegebenen sicheren Weg. Entscheidung, Datenumfang, gegebenenfalls Ablehnungsgrund und Versand werden dokumentiert.'])},
  '010': {fields:operational('Getrennte Verwaltung freiwilliger Entscheidungen',field('purpose','Konkreter Zweck Datenarten und Empfänger',undefined,true),field('choice','Erklärung Information Nachweis Widerruf und Umsetzung',undefined,true)),sections:S(['Erklärung und Systembezug','In CareSuite werden freiwillige Einwilligungen mit konkretem Zweck, Inhalt, Version, betroffener Person, nachgewiesener Vertretung und Erklärungsdatum zugeordnet. Fotoveröffentlichung, zusätzliche Kommunikation und andere unabhängige Zwecke werden getrennt behandelt. Eine allgemeine Anmeldung gilt nicht als Einwilligung für sämtliche Funktionen.'],['Widerruf','Widerrufe werden ab Eingang für die Zukunft umgesetzt. Erforderliche Empfänger erhalten die Information, betroffene Freigaben werden beendet und die verbleibende Rechtsgrundlage wird geprüft. Frühere rechtmäßige Verarbeitung wird nicht rückwirkend unzulässig.'],['Abgrenzung','Verarbeitung für notwendige Vertrags-, Arbeits-, Pflege- oder gesetzliche Dokumentationsaufgaben benötigt ihre eigene tragfähige Rechtsgrundlage. Der Einwilligungseintrag ersetzt weder eine Auftragsverarbeitungsvereinbarung noch Geräteberechtigungen oder Nachweise einer Vertretungsbefugnis.'])},
  '011': {fields:operational('IT-Sicherheit und Datensicherung',field('owners','Betriebsverantwortliche und Notfallkontakte',undefined,true),field('backup','Sicherungsumfang Intervalle Wiederherstellungsziele und Nachweise',undefined,true)),sections:S(['Plattform und Datenfluss',system+' Supabase unterstützt Authentifizierung, PostgreSQL, Dateien und serverseitige Funktionen; das zugeordnete Produktionsprojekt liegt in '+F.productionDatabaseRegion+'. Webauslieferung kann Vercel verwenden. '+optional],['Schutz und Nachweis',security],['Sicherung und Betrieb','Das Sicherungskonzept muss Datenbank und Dateien, erforderliche Metadaten, Aufbewahrung, Zugriffsrechte und eine sichere Wiederherstellung zusammen behandeln. Zulässiger Datenverlust und Wiederanlaufziel sind betrieblich zu vereinbaren und praktisch zu prüfen. Ein PDF-Download ist keine vollständige Plattformdatensicherung.'],['Störung und Vorfall',incident])},
  '012': {fields:operational('Betrieb bei CareSuite-Ausfall und Wiederherstellung',field('plan','Verantwortliche Ersatzverfahren und erreichbare Kontakte',undefined,true),field('test','Letzter Test Ergebnis Wiederanlaufziel und offene Maßnahmen',undefined,true)),sections:S(['Versorgung sichern','Bei Ausfall prüft die verantwortliche Organisation Zugang, Gerät, Verbindung und Plattformstatus. Dringliche Versorgungs- und Notfallaufgaben werden über die betrieblich festgelegten Ersatzwege fortgeführt. Die Erreichbarkeit von CareSuite ist kein Ersatz für einen medizinischen Notruf oder betriebliche Notfallnummern.'],['Nachweise und Synchronisierung','Ersatzdokumentation enthält wirkliche Leistungszeiten, handelnde Person und Anlass. Offline vorliegende GPS-Ereignisse und noch nicht übertragene Dateien werden vor erneuter Eingabe geprüft. Nach Wiederanlauf werden Doppelungen, unvollständige Datensätze und Konflikte nachvollziehbar geklärt.'],['Wiederherstellung','Wiederherstellung erfolgt durch berechtigte Betriebsverantwortliche aus geprüften Sicherungen. Aktenzuordnung, Dateivollständigkeit und Berechtigungen werden vor Freigabe kontrolliert. Ausgangszustand, Quelle, Zeitraum und Ergebnis werden protokolliert. Diese Vorlage setzt keine bereits getestete automatische Wiederherstellung voraus.'])},
  '013': {fields:operational('Personenbezogene Vergabe und Entzug von CareSuite-Rechten',field('user','Person Konto Mandant Rolle und benötigte Einzelrechte',undefined,true),field('approval','Antrag Freigabe Beginn Ende und Kontrollnachweis',undefined,true)),sections:S(['Vergabe',access+' Identität, fachliche Aufgabe und erforderliche Aktenzuordnung werden vor Einrichtung geprüft. Rechte sind auf das erforderliche Maß zu begrenzen.'],['Änderung und Entzug','Versetzung, Vertretung, Ende einer Vollmacht und Austritt führen zur zeitnahen Überprüfung. Zugriff, aktive Sitzungen, Gerätezuordnungen, geteilte Dateien und verbundene Systeme werden jeweils betrachtet. Der Entzug eines Zugangs löscht aufbewahrungspflichtige Dokumentation nicht.'],['Nachweis','Antrag, freigebende Person, tatsächlich eingerichtete Rechte und Abschlusskontrolle bleiben nachvollziehbar. Fehlfreigaben erhalten eine Vorfallprüfung.'])},
  '014': {fields:operational('Nachvollziehbarkeit von CareSuite-Änderungen und Zugriffen',field('log','Tatsächlich protokollierte Ereignisse Speicherorte und Rechte',undefined,true),field('policy','Zweck Auswertung Frist und betriebliche Freigabe',undefined,true)),sections:S(['Zweck und Umfang','Sicherheits- und Verwaltungsereignisse unterstützen Kontoschutz und Nachvollziehbarkeit. Nicht jedes fachliche Lesen wird allein durch diese Vorlage als vollständig protokolliert zugesichert. Der reale Ereignisumfang wird je Funktion anhand der Betriebsnachweise eingetragen.'],['Auswertung','Protokolle dürfen nur durch berechtigte Personen für den festgelegten Sicherheits-, Nachweis- oder Prüfzweck ausgewertet werden. Pauschale Leistungs- und Verhaltensüberwachung wird nicht durch eine technische Protokollmöglichkeit legitimiert.'],['Dokumentenfassungen','Im neuen Dokumentenkatalog tragen Entwürfe eine feste Katalogkennung, Dokument-ID und Fassung. PDF-Dateien erhalten einen aus ihren tatsächlichen Bytes berechneten SHA-256-Prüfwert. Die vorgesehene geschützte Aktenablage und Nachfolgefassungen sind vor Betrieb separat nachzuweisen. Eine ID oder Prüfsumme verhindert keine Kopie und ist kein externes Zertifikat.'])},
  '015': {fields:operational('Mobile Nutzung von CareSuite HealthOS',field('device','Gerät Eigentümer Freigabe und betreuende Stelle',undefined,true),field('permissions','Benötigte App-Rechte und betriebliche Nutzungsvorgaben',undefined,true)),sections:S(['Zugang und Geräte',system+' Die Organisation entscheidet über zugelassene Dienstgeräte. Private Geräte bedürfen einer getrennten Vereinbarung. Konten werden persönlich genutzt und Geräte mit geeigneter Sperre und aktuellen Sicherheitsupdates geschützt.'],['Berechtigungen','Kamera, Fotos, Dateien und Mikrofon werden nur für bewusst verwendete Dokumentations- oder Kommunikationsfunktionen freigegeben. Benachrichtigungen werden mit Blick auf sichtbare Inhalte auf gesperrten Geräten konfiguriert. Biometrische Entsperrung verwendet die Entscheidung des Geräts; die App erhält dadurch keine Fingerabdruck- oder Gesichtsmerkmale.'],['Standort und lokale Daten',gps+' Noch nicht synchronisierte Daten und lokale Downloads sind beim Gerätewechsel zu berücksichtigen. Ein Entzug von Geräterecht kann die betreffende Funktion einschränken und muss organisatorisch aufgefangen werden.'],['Verlust und Rückgabe','Verlust oder fremder Zugriff werden unverzüglich gemeldet. Die Organisation sperrt Konten und prüft verbliebene lokale Dateien. Eine Fernlöschfunktion für das gesamte Endgerät wird durch CareSuite nicht zugesichert. Betriebliche Dateien werden bei Rückgabe oder vereinbartem Ende der privaten Gerätenutzung kontrolliert entfernt.'])},
  '016': {fields:operational('Elektronische Leistungsbestätigung und Unterschrift',field('procedure','Freigegebenes Verfahren Vertretungsprüfung und Kostenträgervorgaben',undefined,true),field('evidence','Erklärung Leistung Zeitraum Fassung und Nachweis',undefined,true)),sections:S(['Was bestätigt wird',signatures],['Wahrheit und Entscheidungsfreiheit','Bestätigt werden nur tatsächlich erbrachte Leistungen und die konkret vorgelegte Erklärung. Leere Nachweise, zukünftige Leistungen oder unbekannte Anhänge werden nicht vorsorglich unterschrieben. Ablehnung, Vertretung, fehlende Einwilligungsfähigkeit und technische Probleme werden ohne fingierte Unterschrift dokumentiert.'],['Korrekturen und Aufbewahrung','Nachträgliche Änderungen erhalten eine nachvollziehbare Fassung und soweit erforderlich eine erneute Bestätigung. Die ursprüngliche Erklärung bleibt nach dem freigegebenen Verfahren nachweisbar. Ein Hash bestätigt die Übereinstimmung mit einer bestimmten Datei, nicht die Identität oder Vertretungsmacht der zeichnenden Person.'])},
  '017': {fields:operational('Export Archivierung und Aktenzuordnung',field('scope','Akten Datenklassen Zeitraum Empfänger und Freigabe',undefined,true),field('format','Benötigte Formate sichere Übergabe und Aufbewahrung',undefined,true)),sections:S(['Auswahl und Datenübernahme','Der Office-Dokumentenkatalog verwendet eine zentrale Definition. Nach Auswahl von Organisation und zugeordneter Klienten-, Personal- oder Unternehmensakte können freigegebene gespeicherte Stammdaten übernommen werden. Die Quelle und die zum Zeitpunkt der Erstellung verwendeten Angaben werden im Entwurf festgehalten. Fachliche Leistungs-, Gesundheits- oder Vertragsangaben werden nur übernommen, wenn hierfür eine belegte Anbindung und Berechtigung bestehen. Unbekannte Angaben bleiben auszufüllen.'],['Ausgabe und Verantwortung','PDF, Ausdruck und bearbeitbare Word-Datei sind unterschiedliche Ausgaben derselben Vorlage. Eine lokal geänderte Word-Datei ist nicht automatisch die in der Akte gespeicherte PDF-Fassung. Downloads und Ausdrucke müssen beim Empfänger gegen fremden Zugriff geschützt werden.'],['Identität und Archiv',signatures+' Katalog-ID, Dokument-ID, Vorlagenversion, Dokumentfassung und Datei-Prüfwerte dienen der Zuordnung. Bearbeitungen verändern die Datei-Prüfwerte. Unveränderliche Aktenablage, Rechteprüfung und technische Signierung dürfen erst nach ihrem realen Betriebsnachweis als aktiv bestätigt werden.'])},
};

const software: Record<string, Content> = {
  '001': {layout:'contract',fields:operational('Nutzungsvereinbarung zwischen CareSuite und einer Organisation',field('provider','Anbieter',provider),field('contact','Vertretungsberechtigte Person der nutzenden Organisation',undefined,true),field('begin','Nutzungsbeginn und einbezogene Anlagen',undefined,true)),sections:S(
    ['§ 1 Parteien und Anwendung',`Anbieter ist ${provider} Vertragspartner ist die im Dokumentkopf bezeichnete Organisation, vertreten durch die hierzu berechtigte Person. Die Vereinbarung betrifft die Bereitstellung von CareSuite HealthOS für ihre betrieblichen Gesundheits-, Pflege-, Assistenz- und Sozialabläufe. Eine einzelne Portalnutzerin oder ein einzelner Portalnutzer wird dadurch nicht an Stelle der Organisation zum Auftraggeber.`],
    ['§ 2 Zugang und Nutzungsrecht',system+' Die Organisation erhält für die Dauer der vereinbarten Nutzung ein einfaches Recht, die bereitgestellten Funktionen für ihre eigenen rechtmäßigen betrieblichen Zwecke zu nutzen und dazu berechtigte Personen einzurichten. Eine Weiterveräußerung fremder Zugänge, Umgehung von Zugriffsschutz oder Nutzung fremder Mandantendaten ist nicht erlaubt. Rechte an eingegebenen Inhalten verbleiben bei den dazu berechtigten Personen beziehungsweise der Organisation.'],
    ['§ 3 Kostenloser Funktionsumfang','Die aktuell kostenlos bereitgestellten CareSuite-Funktionen werden kostenlos genutzt. Die kostenlose Nutzung löst weder eine automatische kostenpflichtige Verlängerung noch eine Pflicht zur Beauftragung künftiger Zusatzangebote aus. Künftige kostenpflichtige Zusatzfunktionen benötigen eine gesonderte transparente Vereinbarung. Geplante Funktionen, Schnittstellen und Zahlungsdienste gelten erst bei ausdrücklicher Bereitstellung und erforderlicher Freigabe als nutzbar. Kosten eigener Geräte, Internetzugang und gesondert beauftragter externer Dienste trägt die Organisation nach ihren jeweiligen Verträgen.'],
    ['§ 4 Verantwortung der Organisation',roles+' Die Organisation stellt rechtmäßige Inhalte, geeignete Rollen, qualifiziertes Personal und aktuelle Vertretungsnachweise sicher. Medizinische, pflegerische, arbeitsrechtliche und abrechnungsbezogene Entscheidungen verbleiben bei den zuständigen Personen. Hinweise und KI-Ausgaben sind vor Verwendung zu prüfen.'],
    ['§ 5 Konten und Sicherheit',access+' '+security+' Missbrauch, fremder Kontozugriff und sicherheitsrelevante Fehler werden unverzüglich gemeldet. Sperrungen werden auf den erforderlichen Umfang begrenzt und der Organisation soweit rechtlich und sicherheitstechnisch möglich erläutert.'],
    ['§ 6 Datenschutz und externe Dienste','Für personenbezogene Auftragsdaten werden eine wirksame Auftragsverarbeitungsvereinbarung und die dazugehörigen freigegebenen Anlagen einbezogen. '+optional+' Eine externe Verbindung wird erst nach Prüfung des Datenumfangs, der Berechtigungen und der Verträge aktiviert. Gesundheitsdaten werden nicht für allgemeine Werbung oder den Verkauf von Daten freigegeben.'],
    ['§ 7 Betrieb und Änderungen','Die Vereinbarung enthält keine feste Verfügbarkeitsquote oder garantierte Reaktionszeit. Gesondert vereinbarte Betriebszusagen bleiben maßgeblich. Wesentliche Änderungen werden nachvollziehbar beschrieben. Die Organisation hält ein geeignetes Ersatzverfahren für Versorgungs- und Nachweisaufgaben vor. Änderungen der Kernleistungen und Vertragsbedingungen werden transparent behandelt; daraus wird kein unbegrenztes einseitiges Änderungsrecht abgeleitet.'],
    ['§ 8 Nachweise und Erklärungen',signatures+' Ein Dokument mit Entwurfsmarke bleibt bis zur passenden Freigabe ein Entwurf. Der neue Katalog weist keine externe Zertifizierung allein durch CareSuite-Kennzeichnung aus.'],
    ['§ 9 Beendigung und Herausgabe','Die Organisation kann die kostenlose Nutzung in Textform gegenüber CareSuite beenden. Zwingende Rechte zur außerordentlichen Beendigung bleiben bestehen. Eine Beendigung durch den Anbieter wird unter Berücksichtigung der betroffenen Betriebsabläufe, einer erforderlichen Übergabe und gesetzlicher Pflichten abgewickelt; konkrete Fristen und etwaige besondere Laufzeitabreden werden individuell festgelegt. Export, Übergabe, Sperrung und Löschung werden mit dem Auftraggeber vor Abschluss geklärt. Eine Kontolöschung ersetzt diese Abstimmung nicht.'],
    ['§ 10 Haftung Anlagen und Vereinbarungen','Die Haftung richtet sich nach den anwendbaren gesetzlichen Regeln. Eine pauschale Haftungsfreistellung, eine nicht geprüfte Gerichtsstandsklausel und eine automatische Ersetzung unwirksamer Bestimmungen werden nicht vereinbart. Nutzungsbeschreibung, Datenschutzinformation, Auftragsverarbeitungsvereinbarung und individuell einbezogene Anlagen werden mit Stand ausgehändigt. Individuelle Vereinbarungen werden nachvollziehbar festgehalten.'])},
  '002': {fields:operational('Beschreibung des verfügbaren und abzugrenzenden Funktionsumfangs',field('enabled','Für die Organisation tatsächlich aktivierte Funktionen und Edition',undefined,true)),sections:S(['Anwendungen und Zielgruppe',system],['Betriebliche Funktionen','Die Plattform unterstützt Organisations- und Stammdatenverwaltung, Personal- und Klientenbezug, Dienst- und Einsatzplanung, Kommunikation, Dokumentation, Leistungsnachweise und administrative Ausgaben. Pflege- und stationäre Fachfunktionen setzen entsprechende Freigabe und fachliche Zuständigkeit voraus. Die mobile Edition kann auf Mitarbeiter- und Klientenportale beschränkt sein; ein Web-Verwaltungsumfang wird nicht allein aus der App-Installation abgeleitet.'],['Daten und Rollen',data+' '+access],['Zentraler Dokumentenkatalog','Der neue Office-Katalog ist eine gemeinsame Quelle für die aufrufenden Module. Er enthält bearbeitbare Vorlagentexte, kontrollierte Stammdatenübernahme, PDF-Ausgabe, Druck und eine vorgesehene geschützte Aktenzuordnung. Die produktive Aktivierung der neuen Datenbank- und Ablagefunktionen ist gesondert nachzuweisen. Eine Titelabdeckung des Katalogs bedeutet keine fachliche oder juristische Freigabe aller Dokumente.'],['Optionale Dienste und Grenzen',optional+' CareSuite trifft keine eigene medizinische oder rechtliche Entscheidung. Ein Name in einer Modulliste oder Entwicklungsplanung ist keine Bereitstellungszusage.'])},
  '003': {fields:operational('Nutzungsregeln für die Verwaltung',field('admins','Benannte Administrationskonten und zuständige Freigabestelle',undefined,true)),sections:S(['Aufgaben und Rechte',access],['Einrichtung','Konten werden nach Identitäts- und Zuständigkeitsprüfung eingerichtet. Beschäftigte, Klienten und Vertretungen werden der richtigen Organisation und Person zugeordnet. Rollen, sensible Zugriffe, Exportrechte und Integrationen werden getrennt freigegeben. Testdaten und echte Akten dürfen nicht verwechselt werden.'],['Bearbeiten und Ausgeben','Vor Datenübernahme, PDF-Erstellung, Druck oder Aktenablage werden aktuelle Quelle, Personenzuordnung und erforderliche Angaben geprüft. Vertrags- und Fachtexte werden passend freigegeben. Eine lokale Word-Änderung wird erst nach kontrollierter Übernahme als neue Aktenfassung geführt.'],['Kontrolle und Support','Die Verwaltung prüft Rechte bei Rollenwechsel und Austritt. Support erhält einen begrenzten, dokumentierten Auftrag. Unnötige Gesundheitsdaten und Zugangsdaten werden nicht an allgemeine E-Mail-Adressen weitergegeben. Vorfälle werden unverzüglich gemeldet.'])},
  '004': {target:'employee',fields:operational('Nutzungsregeln für das Mitarbeiterportal',field('assignment','Freigegebene Tätigkeiten und betriebliche Ansprechperson',undefined,true)),sections:S(['Persönlicher Zugang','Das Mitarbeiterportal wird mit dem eigenen Konto für die übertragenen betrieblichen Aufgaben verwendet. Zugangsdaten und offene Sitzungen werden nicht geteilt. Die eigene Rolle erlaubt nur zugewiesene Akten und Funktionen. Aufbewahrte Ausdrucke und Downloads bleiben vertraulich.'],['Einsätze und Nachweise','Mitarbeitende prüfen zugewiesene Einsätze, tragen tatsächlich erbrachte Leistungen und reale Zeiten ein und dokumentieren Abweichungen. Eintragungen für andere Personen oder nachträgliche Änderungen müssen entsprechend ihrer tatsächlichen Befugnis und dem freigegebenen Verfahren nachvollziehbar bleiben.'],['Mobile Funktionen',gps+' Kamera, Dateien und Mikrofon werden nur für erforderliche freigegebene Aufgaben verwendet. Privatnutzung und ein privates Endgerät setzen eine ausdrückliche Regelung voraus.'],['Bestätigung und Meldung',signatures+' Falschzuordnungen, ausgefallene Synchronisierung und Sicherheitsvorfälle werden über die bekanntgegebenen betrieblichen Wege gemeldet.'])},
  '005': {target:'client',fields:operational('Nutzungsregeln für das Klientenportal',field('representation','Nachgewiesene Vertretung und freigegebene Inhalte',undefined,true)),sections:S(['Eigener Zugang','Das Klientenportal stellt der zugeordneten Person freigegebene Informationen, Termine, Mitteilungen und Nachweise bereit. Angehörige oder Vertretungen erhalten nur einen zulässigen, nachgewiesenen Zugang. Die Verantwortung für die Versorgung und Information verbleibt bei der betreuenden Organisation.'],['Was bestätigt wird',signatures+' Vor Bestätigung können Fragen und Abweichungen an die Organisation gerichtet werden. Eine nicht abgegebene Bestätigung wird nicht durch eine fingierte Unterschrift ersetzt.'],['Datenschutz und Schutz','Bitte schützen Sie Ihren Zugang und schließen Sie die Sitzung an gemeinsam genutzten Geräten. Die Organisation entscheidet, welche eigenen Informationen im Portal sichtbar sind. Die Nutzung gibt keinen allgemeinen Einblick in andere Klientenakten, Personalakten oder Bewegungsprofile von Mitarbeitenden. '+rights],['Kontakt und Dringlichkeit','Fachliche Rückfragen richten Sie an Ihre betreuende Organisation. Technische Plattformfragen können an '+F.email+' gerichtet werden. Gesundheitsdaten werden nicht unverschlüsselt per E-Mail versandt. Bei akuter Gefahr ist der geeignete Notruf zu verwenden; das Portal ist kein dauerhaft überwachter Notrufdienst.'])},
  '006': {fields:[],sections:S(
    ['Geltung und Verantwortlicher',`Diese Erklärung betrifft Website, CareSuite-Webanwendung, mobile App, Portale und verbundene Plattformfunktionen. Verantwortlicher für eigene Plattformzwecke ist ${provider} Nach der vorliegenden Plattforminformation ist derzeit kein Datenschutzbeauftragter bestellt; Anfragen können direkt an die genannte Kontaktadresse gerichtet werden. Eine gesetzlich erforderliche spätere Benennung wird in der veröffentlichten Fassung berücksichtigt.`],
    ['Organisation und Auftragsdaten',roles+' Für Fragen zu Ihrer Pflege-, Personal- oder Leistungsakte wenden Sie sich zunächst an die verantwortliche Organisation. CareSuite unterstützt deren rechtmäßige Bearbeitung.'],
    ['Daten und Herkunft',data+' Die Daten stammen von Ihnen, berechtigten Personen der Organisation, Vertretungen, rechtmäßig verbundenen Systemen und verwendeten Endgeräten. Werden Daten nicht unmittelbar erhoben, erfüllt der Verantwortliche die erforderlichen Informationen nach Art. 14 DSGVO.'],
    ['Zwecke und Rechtsgrundlagen','Eigene Vertrags- und Kontovorgänge erfolgen soweit anwendbar nach Art. 6 Abs. 1 Buchst. b DSGVO, gesetzliche Pflichten nach Buchst. c und erforderliche Sicherheit sowie sachgerechter Support nach Buchst. f mit dokumentierter Interessenabwägung. Geeignete freiwillige Zusatzverarbeitungen erfolgen nach Buchst. a. Der jeweilige Verantwortliche bestimmt die konkrete Grundlage für Fachdaten und zusätzlich eine passende Ausnahme nach Art. 9 Abs. 2 DSGVO für Gesundheitsdaten. Beschäftigtendaten werden unter Beachtung des einschlägigen nationalen Rechts verarbeitet. Eine pauschale Einwilligung für alle Funktionen wird nicht verlangt.'],
    ['Website Anmeldung und Geräte','Beim Seitenaufruf können IP-Adresse, Zeitpunkt, angeforderte Ressource, Geräte- und Browserangaben sowie Fehler- und Sicherheitsinformationen verarbeitet werden. Anmeldung verwendet Konto, Rolle, Mandant und Sitzungsinformationen. Notwendige Gerätespeicherung unterstützt Sitzung und angeforderte Funktionen; soweit § 25 TDDDG anwendbar ist, kommt für unbedingt erforderliche Zugriffe dessen Abs. 2 Nr. 2 in Betracht. Zusätzliche Analyse oder Werbung benötigt eine gesonderte zulässige Grundlage. Biometrische Gerätesperre übermittelt der App keine biometrischen Merkmale.'],
    ['Zusätzliche Betriebsübersicht','Die Web- und Desktop-Plattform kann Seitenaktivität, bestätigte Anmeldungen, Registrierungsschritte und technische Fehler für die Betriebsübersicht erfassen. Die hierfür erzeugte Kennung bleibt im Arbeitsspeicher des Fensters; bestätigte Konten können serverseitig dem Konto und Unternehmen zugeordnet werden. Do Not Track und Global Privacy Control stoppen diese zusätzliche Erfassung. Unvollständige Registrierungen enthalten dabei keine Formularinhalte; Passwörter und Akteninhalte werden nicht in diese Übersicht übernommen. Die bestehende Information benennt 90 Sekunden Live-Anzeige, Bereinigung inaktiver Seitenmeldungen nach einem Tag, verknüpfter Registrierungsverläufe nach 14 Tagen und Fehlerzusammenfassungen nach 30 Tagen, ausgelöst bei weiteren Betriebsmeldungen. Diese Fristen gelten allein für dieses Verfahren.'],
    ['Mobile Dokumentation und Standort',gps+' Kamera, Fotos, Dateien und Mikrofon werden bei entsprechender Nutzeraktion verarbeitet. Eine Gerätefreigabe ersetzt keine rechtmäßige Grundlage für sensible Aufnahmen oder Standortnutzung. Benachrichtigungen können Geräte- beziehungsweise Push-Kennungen und technische Zustelldaten benötigen. Sichtbare Inhalte auf gesperrten Geräten sind datensparsam zu konfigurieren.'],
    ['Dienstleister und internationale Verarbeitung',`Supabase unterstützt Authentifizierung, Datenbank, Dateien, Echtzeit und serverseitige Funktionen. Das zugeordnete Produktionsprojekt liegt in ${F.productionDatabaseRegion}. Vercel kann die Webanwendung über globale Infrastruktur ausliefern. ${optional} Aktive Empfänger, Verträge, weitere Verarbeitungsorte und Übermittlungsmechanismen sind in der jeweils freigegebenen Dienstleisteranlage nachzuweisen. Je nach Anbieter kann Verarbeitung außerhalb des EWR stattfinden; anwendbare Angemessenheitsbeschlüsse, Standardvertragsklauseln und ergänzende Maßnahmen werden konkret geprüft. Es wird keine ausschließliche Verarbeitung aller Plattformdaten in Deutschland zugesichert.`],
    ['KI und menschliche Prüfung','Optionale freigegebene KI-Funktionen können Eingaben, ausgewählten Kontext, Antworten, technische Kennungen und bei Sprachfunktionen Audio oder Transkripte verarbeiten. Sensible Daten werden nur im erforderlichen Umfang an das tatsächlich freigegebene Verfahren übermittelt. Ausgaben können falsch sein und werden vor fachlicher Verwendung geprüft. Eine ausschließlich automatisierte Entscheidung mit erheblicher Wirkung wird durch diese Datenschutzerklärung nicht eingerichtet.'],
    ['Aufbewahrung und Schutz',retention+' '+security],
    ['Rechte Kontakt und Beschwerde',rights+' Für eigene CareSuite-Verarbeitungen richten Sie Ihr Anliegen an '+F.email+'. Für Mandantendaten ist die im jeweiligen Verhältnis benannte Organisation zuständig. Die zuständige Datenschutzaufsichtsbehörde kann unabhängig davon angerufen werden.'],
    ['Erforderliche Angaben und Änderungen','Erforderliche Zugangsdaten und Zuordnungen ermöglichen das angeforderte Konto und freigegebene Arbeitsverfahren. Optionale Funktionen werden gesondert geprüft. Nichtbereitstellung kann die betreffende Funktion verhindern. Eine App-Store-Installation unterliegt daneben den eigenen Datenschutzbedingungen des Store-Betreibers. Die öffentlich freigegebene Erklärung wird bei wesentlichen Änderungen aktualisiert. Dieser Dokumententwurf ersetzt ihre Veröffentlichung und die erforderliche individuelle Mandanteninformation nicht.'])},
  '007': {target:'employee',layout:'contract',fields:operational('Vereinbarung zur dienstlichen App-Nutzung',field('device','Dienstgerät oder gesonderte Privatgerätevereinbarung',undefined,true),field('duties','Aufgaben Arbeitszeiten Schulung und Ersatzverfahren',undefined,true)),sections:S(['§ 1 Aufgaben und Bereitstellung','Der Arbeitgeber stellt den persönlichen Zugang für die vereinbarten dienstlichen Aufgaben bereit und unterweist in Bedienung, Datenminimierung und Meldewegen. '+system+' Eine Pflicht, ein privates Gerät oder einen privaten Datenvertrag bereitzustellen, entsteht hierdurch nicht.'],['§ 2 Umgang mit Konten und Inhalten',access+' Dienstliche Einträge sind sachlich, erforderlich und wahrheitsgemäß. Zugangsdaten dürfen nicht geteilt und Klienteninformationen nicht in private Konten oder unfreigegebene Apps kopiert werden.'],['§ 3 Zeit und Standort',gps+' Nutzungsanforderungen erfolgen im arbeitsrechtlich vereinbarten Rahmen. Erreichbarkeit außerhalb der Arbeitszeit und zusätzliche Überwachung werden durch diese Vereinbarung nicht pauschal angeordnet. Erforderlichkeit, Information und gegebenenfalls Mitbestimmung werden vor Aktivierung geklärt.'],['§ 4 Datenschutz und Bestätigung','Die getrennte Datenschutzinformation für Beschäftigte wird ausgehändigt. '+signatures+' Eine Empfangsbestätigung ist keine Zustimmung zu unbestimmter Datenverarbeitung.'],['§ 5 Störung und Ende','Bei Geräte- oder Verbindungsstörung wird das bekannte Ersatzverfahren verwendet. Fehler und Vorfälle werden zeitnah gemeldet. Bei Austritt werden Zugänge entzogen und dienstliche Daten sowie Geräte kontrolliert übergeben. Gesetzliche Arbeitnehmerrechte bleiben gewahrt.'])},
  '008': {target:'employee',fields:operational('Unterweisung und Kompetenznachweis',field('trainer','Unterweisende Person Datum und geprüfte Aufgaben',undefined,true),field('result','Praktische Durchführung Fragen Ergebnis und Nachschulung',undefined,true)),sections:S(['Persönlicher Einstieg','Unterwiesen wird in eigener Anmeldung, richtigen Rollen und Aktenzuordnungen, sicherem Kennwort, Gerätesperre und betrieblichen Kontaktwegen. Die unterweisende Person prüft den tatsächlichen Zugriff auf die zugewiesene Umgebung.'],['Praktische Arbeit','Die unterwiesene Person übt Einsatzprüfung, richtige Zeit- und Leistungseinträge, sachliche Dokumentation, Dateiübernahme, Umgang mit Abweichungen und kontrollierte Synchronisierung. Testbeispiele enthalten keine unnötigen echten Gesundheitsdaten.'],['Datenschutz und Grenzen',access+' '+signatures+' Standort, Medienaufnahmen, Push und externe Dienste werden nur im tatsächlich freigegebenen Umfang behandelt.'],['Abschluss','Der Nachweis hält tatsächlich durchgeführte Übungen und offene Fragen fest. Eine Teilnahmebestätigung bescheinigt keine unbeobachtete praktische Kompetenz. Wiederholung oder Nachschulung wird konkret terminiert.'])},
  '009': {target:'employee',fields:operational('Information zur dienstlichen Standort- und Fahrtenaufzeichnung',field('scope','Zulässige Fahrten Zeiträume Zwecke und Rechtsgrundlage',undefined,true),field('recipients','Zugriff Löschfrist Alternative und Beteiligung',undefined,true)),sections:S(['Funktion und Daten',gps],['Rechtmäßige Einführung','Der Arbeitgeber legt vor Beginn den konkreten Zweck und die erforderliche Datenmenge fest, informiert die betroffenen Beschäftigten und prüft Mitbestimmungsrechte. Eine allgemeine Standortfreigabe am Gerät ist keine Einwilligung in unbegrenzte Überwachung. Eine Einwilligung im Beschäftigungsverhältnis setzt tatsächliche Freiwilligkeit voraus.'],['Dienstlicher Umfang','Aufzeichnung, Sichtbarkeit und Auswertung werden auf den erforderlichen dienstlichen Zusammenhang begrenzt. Freizeit, Privatfahrten und sachfremde Bewegungsprofile werden ausgeschlossen. Der Klientenzugang ermöglicht keine allgemeine dauerhafte Mitarbeiterortung.'],['Fehler und Rechte','Ungenaue Koordinaten, Verbindungsstörung und Nachübertragung werden bei Nachweisen berücksichtigt. Standortabweichung allein beweist keine nicht erbrachte Leistung. '+rights])},
  '010': {fields:operational('Freigabe einer optionalen Integration oder KI-Funktion',field('service','Dienst aktivierte Schnittstelle und Datenfluss',undefined,true),field('approval','Zweck Rechtsgrundlage Vertrag Rechte und Freigabe',undefined,true)),sections:S(['Technischer Umfang',optional],['Prüfung vor Verbindung','Die Organisation prüft Anbieter, konkrete Datenarten, Empfängerrolle, Berechtigungen, Auftragsverarbeitung, internationale Übermittlungen, Aufbewahrung und sichere Widerrufsmöglichkeit. OAuth-Freigaben werden auf notwendige Rechte begrenzt. Eine Anzeige der Schnittstelle berechtigt nicht zur Übertragung.'],['KI und sensible Inhalte','KI ist eine Arbeitshilfe. Sensible Daten und Gesundheitsdaten werden nur nach ausdrücklicher organisatorischer Verfahrensfreigabe und im erforderlichen Umfang übermittelt. Antworten werden fachlich kontrolliert; sie erteilen keine medizinische, juristische oder abrechnungsrechtliche Freigabe.'],['Kontrolle und Ende','Test, tatsächlich verbundene Konten, verwendete Berechtigungen und freigegebene Zwecke werden dokumentiert. Bei Entzug werden Verbindung, noch gültige Rechte und gespeicherte Daten beim Dienst getrennt geprüft.'])},
  '011': {fields:operational('Register eingesetzter technischer Dienstleister',field('active','Tatsächlich aktive Dienste Vertragspartner Vertragsstand und Nachweis',undefined,true),field('transfers','Weitere Verarbeitungsorte Übermittlungsmechanismen und genehmigende Stelle',undefined,true)),sections:S(['Supabase',`Im Projekt werden Supabase-Authentifizierung, PostgreSQL, Storage, Echtzeit und Edge Functions verwendet. Die zugeordnete Produktionsdatenbank liegt in ${F.productionDatabaseRegion}. Konto-, Mandanten-, Datei- und erforderliche Fachdaten werden funktionsbezogen verarbeitet. Vertragliche Gesellschaft, Unterauftragnehmer, Supportzugriffe und weitere Verarbeitungsorte sind im aktiven Anbieter-Nachweis zu ergänzen; ein Datenbankstandort allein belegt sie nicht.`],['Webauslieferung und Benachrichtigungen','Vercel kann Webhosting, Auslieferung, Anfrage- und Sicherheitsverarbeitung übernehmen. Bei aktivierten mobilen Benachrichtigungen kann Expo Push Zustellkennungen und technische Mitteilungsdaten verarbeiten. Die Organisation prüft die tatsächlich aktive Konfiguration und begrenzt Inhalte.'],['Karten KI und Schnittstellen',optional],['Genehmigung und Fortschreibung','Das Register kennzeichnet jeden Dienst als aktiv, optional freigegeben, nicht aktiviert oder noch zu prüfen. Ein optionaler Dienst wird nicht pauschal als bereits beauftragter Unterauftragsverarbeiter ausgegeben. Rechtsträger, konkrete Leistung, Datenklassen, vertragliche Rolle, internationale Grundlage und Änderungen werden je aktivem Dienst nachgewiesen.'])},
  '012': {layout:'contract',fields:operational('Betriebsvereinbarung zur digitalen Arbeitsorganisation',field('parties','Arbeitgeber und zuständige Interessenvertretung',undefined,true),field('scope','Beschäftigte aktive Verfahren Rechte und Fristen',undefined,true)),sections:S(['§ 1 Geltung und Beteiligung','Diese Vereinbarung wird nur durch den Arbeitgeber und die hierfür zuständige Interessenvertretung geschlossen. Sie betrifft die benannten CareSuite-Verfahren und betroffenen Beschäftigten. Beteiligung nach § 87 BetrVG beziehungsweise den einschlägigen personalvertretungsrechtlichen Vorschriften wird vor Einführung geprüft. Die Softwarefreigabe ersetzt sie nicht.'],['§ 2 Zwecke und Daten','Zulässige Zwecke sind die konkret vereinbarte Arbeitsorganisation, Einsatzplanung, richtige Zeit- und Leistungsdokumentation sowie notwendige Sicherheit. '+data+' Tatsächlich verarbeitete Beschäftigtendaten und Auswertungen sind in der Anlage einzeln abzugrenzen.'],['§ 3 Begrenzung von Auswertungen','Heimliche oder pauschale Leistungs- und Verhaltensbewertung wird nicht vereinbart. Zugriffe und Auswertungen sind zweckgebunden, nachvollziehbar und auf Berechtigte zu begrenzen. Standort-, Protokoll- und KI-Verfahren benötigen eine gesonderte Regelung ihres Umfangs. Disziplinarische oder automatisierte Folgen werden durch einen Softwarehinweis nicht vorweggenommen.'],['§ 4 Standort und Endgeräte',gps+' Private Geräte sind freiwillig gesondert zu vereinbaren; notwendige betriebliche Alternativen werden festgelegt. Erreichbarkeit in der Freizeit wird nicht vorausgesetzt.'],['§ 5 Schutz Fristen und Beteiligtenrechte',security+' '+retention+' Beschäftigte erhalten verständliche Informationen und sichere Möglichkeiten zur Berichtigung und Beschwerde.'],['§ 6 Änderungen und Abschluss','Wesentliche Erweiterungen werden vor Einsatz gemeinsam bewertet. Geltungsdauer, Kündigung, Nachwirkung soweit rechtlich zulässig und konkret einbezogene Anlagen werden betriebsspezifisch ergänzt. Diese Vorlage enthält hierzu keine unbegründeten Standardfristen.'])},
  '013': {target:'employee',layout:'contract',fields:operational('Vereinbarung zur freiwilligen Nutzung privater Endgeräte',field('device','Privates Gerät erlaubte Nutzung und beteiligte Personen',undefined,true),field('costs','Kosten Auslagen Alternative und Ende der Nutzung',undefined,true)),sections:S(['§ 1 Freiwilligkeit und Alternative','Die Nutzung des benannten privaten Endgeräts wird für den konkret vereinbarten dienstlichen Zweck gestattet. Ein geeignetes betriebliches Ersatzverfahren wird vereinbart. Private Gerätedaten und private Kommunikation werden hierdurch nicht dem Arbeitgeber zur Einsicht freigegeben.'],['§ 2 Technische Voraussetzungen','Gerätesperre, unterstützte App, aktuelle Sicherheitsupdates und persönlicher Zugang werden vor Freigabe geprüft. Dienstliche Dateien werden von privaten Ablagen getrennt gehalten. Die Vereinbarung bescheinigt keine vollständige Geräteverschlüsselung, zentrale Geräteverwaltung oder automatische Fernlöschung.'],['§ 3 Berechtigungen und Zeitraum','Kamera, Dateien, Mikrofon, Mitteilungen und Standort werden nur im notwendigen freigegebenen dienstlichen Umfang genutzt. '+gps+' Eine private Nutzung außerhalb des Dienstes begründet keine betriebliche Erreichbarkeit.'],['§ 4 Aufwand Haftung und Vorfälle','Kosten, Datenverbrauch und notwendige Erstattungen werden ausdrücklich geregelt. Verlust, Gerätewechsel oder fremder Zugriff werden unverzüglich gemeldet. Haftung und Arbeitnehmerrechte richten sich nach den gesetzlichen und konkret vereinbarten Regeln; eine pauschale Überwälzung aller Schäden wird nicht vereinbart.'],['§ 5 Ende und Trennung','Die private Gerätenutzung kann nach dem vereinbarten Verfahren beendet werden. Dienstliche Dateien, Sitzungen und Verbindungen werden kontrolliert entfernt oder übertragen, ohne private Daten pauschal zu löschen. Aufbewahrungspflichtige Nachweise verbleiben sicher beim Arbeitgeber.'])},
  '014': {layout:'contract',fields:operational('Begrenzter sicherer Supportzugriff',field('request','Auftrag Fehler betroffene Funktion und freigebende Person',undefined,true),field('limits','Zugriffsumfang Zeitraum sichere Übermittlung und Abschlusskontrolle',undefined,true)),sections:S(['§ 1 Anlass und Beteiligte',`Technischer Support erfolgt durch ${F.provider} oder ausdrücklich verpflichtete beauftragte Personen. Die Organisation beauftragt ausschließlich die benannte Prüfung. Produktkenntnis allein berechtigt nicht zum Zugriff auf ihre Akten.`],['§ 2 Begrenzung und Vertraulichkeit','Zugang, Dauer, Akten und Dateien werden auf das zur Fehlerklärung erforderliche Maß begrenzt. Nach Möglichkeit werden anonymisierte Beispiele oder technische Diagnoseangaben verwendet. Passwörter werden nicht weitergegeben. Kopien und Testausgaben werden kontrolliert behandelt.'],['§ 3 Daten und sichere Wege','Gesundheits- und Personaldaten werden nicht unverschlüsselt an allgemeine Supportadressen gesendet. Erforderlicher Zugriff auf Auftragsdaten bleibt an dokumentierte Weisung und Auftragsverarbeitungsvereinbarung gebunden. Erweiterungen benötigen eine nachvollziehbare Freigabe.'],['§ 4 Abschluss','Durchgeführte Schritte, tatsächliche Zugriffe, Ergebnis und verbleibende Maßnahmen werden dokumentiert. Temporäre Rechte werden entzogen und notwendige Löschung von Supportkopien geprüft. Ein Supportauftrag ist keine technische oder rechtliche Abnahme des gesamten Systems.'])},
  '015': {fields:operational('Dokumentierte Weisungen zur Auftragsverarbeitung',field('authority','Weisungsberechtigte Person Auftraggeber und AVV-Stand',undefined,true),field('instruction','Weisung Daten Umfang Beginn Ende und Ausführungsnachweis',undefined,true)),sections:S(['Befugnis und Bezug',roles+' Weisungen benennen verantwortliche Organisation, zugrunde liegende Vereinbarung, berechtigte Person, betroffene Daten und konkrete Handlung.'],['Zulässiger Umfang','Verarbeitung, Supportzugriff, Änderung, Export, Übermittlung, Sperrung und Löschung werden eindeutig bezeichnet. Neue Zwecke oder Empfänger werden vor Ausführung auf Rechtsgrundlage und Vertragsumfang geprüft. Eine unklare Bitte um Zugriff auf alle Akten ist nicht hinreichend.'],['Ausführung und Abweichung','CareSuite dokumentiert Eingang, Rückfragen, Ausführung und Abschluss. Datenschutzrechtlich bedenkliche Weisungen werden dem Auftraggeber unverzüglich zur Klärung angezeigt. Nachweise enthalten nur erforderliche Daten und bleiben über die zuständige Kontaktstelle verfügbar.'])},
  '016': {fields:operational('Plattformwechsel Herausgabe und Vertragsende',field('scope','Vertrag Datenbestände Zielformat Empfänger und Freigabe',undefined,true),field('close','Exportkontrolle Löschauftrag Ausnahmen und Abschlussnachweis',undefined,true)),sections:S(['Planung','Die Organisation bestimmt vor Vertragsende benötigte Daten, Akten, Originale, Dateien, Nachweise und sicher zu übertragende Struktur. Ein Vorlagen-ZIP ist keine vollständige Mandantensicherung. Aktive Zugänge und Integrationen werden im Übergabeplan berücksichtigt.'],['Herausgabe und Kontrolle','Die Parteien vereinbaren tatsächlich verfügbare Formate und sichere Übergabe. Empfänger, Vollständigkeit, Lesbarkeit, Zuordnung und erforderliche Metadaten werden geprüft. Eine organisatorische Kontrolle bestätigt, welche Bestände übernommen sind und welche Abweichungen verbleiben.'],['Löschung und Sperren',retention+' Für Auftragsdaten richtet sich Rückgabe oder Löschung nach der Weisung und der Auftragsverarbeitungsvereinbarung. Fristen und Sicherungskopien werden im konkreten Auftrag festgelegt.'],['Abschluss','Zugänge, verbundene Konten, lokale Kopien und Ausdrucke werden kontrolliert behandelt. Die Organisation bewahrt notwendige gesetzliche Nachweise weiter auf. Vertragsende wird nicht als automatischer Nachweis aller Löschungen verwendet.'])},
  '017': {fields:[field('additional','USt-IdNr Wirtschafts-IdNr Register oder besondere Pflichtangaben soweit vorhanden',undefined,false)],sections:S(['Anbieter',provider],['Einordnung','Die vorliegende Plattforminformation bezeichnet den Anbieter als Einzelunternehmen. Eine geplante Gesellschaft, ein nicht belegtes Handelsregister oder eine erfundene Steuernummer werden hier nicht als bereits bestehende Anbieterangabe eingetragen. Änderungen werden erst anhand der verbindlichen neuen Daten übernommen.'],['Zugang und ergänzende Pflichtangaben','Die Anbieterkennzeichnung ist in Website und App leicht erkennbar, unmittelbar erreichbar und ständig verfügbar bereitzustellen. Erforderliche zusätzliche Angaben nach § 5 DDG werden abhängig von tatsächlicher Rechtsform, Registereintragung, vorhandener Identifikationsnummer und Angebot ergänzt. Eine allgemeine Steuernummer wird nicht allein als Ersatz einer gesetzlichen Identifikationsangabe veröffentlicht.'],['Fachliche Verantwortung','Die Plattform ist ein technisches Organisations- und Dokumentationswerkzeug. Angaben zu einem versorgenden Pflege- oder Betreuungsunternehmen sind dessen eigene Anbieterangaben. Eine Aufnahme in den CareSuite-Dokumentenkatalog verleiht keine behördliche Zulassung oder externe Zertifizierung.'])},
  '018': {target:'employee',fields:operational('Sicherheitsinformation beim Erstzugang',field('contact','Betriebliche Kontaktstelle und freigegebene Aufgaben',undefined,true)),sections:S(['Vor der ersten Arbeit','Prüfen Sie eigene Identität, Organisation, Rolle und zugeordnete Aufgaben. Ändern Sie übergebene vorläufige Zugangsdaten nach dem vorgesehenen Verfahren. Nutzen Sie keine gemeinsamen Konten. Bei falsch sichtbaren Akten unterlassen Sie weitere Einsicht und melden den Fehler.'],['Im Arbeitsalltag','Sperren Sie Geräte bei Unterbrechungen. Prüfen Sie Personenzuordnung vor Dokumentation, Upload und Leistungsbestätigung. Sensible Informationen werden nur in freigegebenen Verfahren verarbeitet; private Messenger, E-Mail und ungeschützte Ablagen sind kein Standardablageort.'],['Mobile Berechtigungen',gps+' Geräterecht wird funktionsbezogen erteilt. Sichtbare Mitteilungen dürfen keine unnötigen Gesundheitsdaten offenlegen.'],['Wenn etwas schiefläuft',incident])},
  '019': {fields:operational('Nachweis ausgehändigter Nutzungs- und Datenschutzunterlagen',field('documents','Tatsächlich übergebene Dokumente Versionen Datum und Empfänger',undefined,true),field('acknowledgement','Art des Empfangsnachweises und offene Fragen',undefined,true)),sections:S(['Empfang','Bestätigt wird ausschließlich der tatsächliche Empfang der einzeln aufgeführten vollständigen Unterlagen. Papier, PDF oder anderer vereinbarter Übermittlungsweg und die jeweilige Fassung werden angegeben. Unbekannte Anhänge werden nicht vorsorglich bestätigt.'],['Erklärung und Grenzen','Eine Empfangsbestätigung ist weder eine pauschale Datenschutz-Einwilligung noch ein Verzicht auf Fragen, Beschwerden oder gesetzliche Rechte. Der Abschluss eines Vertrags und eine freiwillige Einwilligung erfordern ihre eigene eindeutige Erklärung. '+signatures],['Nachweis','Die Organisation ordnet die Bestätigung der richtigen Akte zu und stellt auf Wunsch eine Ausfertigung bereit. Unvollständige Übermittlung oder verweigerter Empfang werden tatsächlich dokumentiert.'])},
  '020': {fields:operational('Bewertung von Softwareänderungen vor betrieblicher Freigabe',field('change','Neue Fassung Funktionen Datenflüsse und betroffene Personen',undefined,true),field('review','Prüfnachweise Zuständigkeiten Ergebnis und offene Bedingungen',undefined,true)),sections:S(['Anlass und Umfang','Bewertet werden Änderungen an Funktionen, Rollen, Datenübernahme, externen Diensten, Standort, KI, Nachweisen und Aufbewahrung. Die tatsächlich eingesetzte Edition und Konfiguration sind maßgeblich. Eine Entwicklungsdatei oder ein Entwurfs-PR ist keine produktive Betriebsfreigabe.'],['Prüfen','Die Organisation prüft fachliche Eignung, Rechte, Mandantentrennung, Datenumfang, Informationspflichten, Verträge, erforderliche Folgenabschätzung und Mitbestimmung. PDF, Druck, Word, Aktenzuordnung, Korrekturen und Ausfallverfahren werden für betroffene Abläufe getrennt betrachtet.'],['Freigabe und Schulung','Freigebende Personen dokumentieren wirkliche Nachweise und noch offene Bedingungen. Nutzer erhalten passende Unterweisung und aktuelle Informationen. Ungeprüfte Funktionen bleiben gesperrt beziehungsweise werden noch nicht für echte Daten verwendet.'],['Grenzen von Kennzeichnung','CareSuite-Bezeichnung, Dokument-ID und SHA-256-Prüfwert dienen Herkunftszuordnung und Dateivergleich. Sie verhindern keinen Diebstahl und ersetzen weder ein Zertifikat einer unabhängigen Stelle noch Rechts- oder Fachfreigabe. Eine entsprechende Aussage wird erst mit tatsächlich belegtem Verfahren verwendet.'])},
};

export function careSuiteSoftwareContent(key: string): Content | undefined {
  const [, category, number] = key.match(/^csdc_([a-z]+)_(\d{3})$/) ?? [];
  return category === 'software' ? software[number] : category === 'datenschutz' ? privacy[number] : undefined;
}

/** Für Versorgungsverträge bleibt die betreuende Organisation Vertragspartner. */
export function careSuiteRelatedSections(title: string, category: string, layout: string, sourceMode: string): CentralDocumentSection[] {
  if(sourceMode === 'original') return [];
  if(category === 'vollmachten' && /Datenschutzinformation/.test(title)) return S(
    ['Verantwortliche Organisation und Software',roles+' '+provider],
    ['Welche Daten zu welchem Zweck verwendet werden',data+' Zweck sind Aufnahme, vereinbarte Versorgung, sichere Organisation, fachliche Dokumentation, Kommunikation und zulässige Leistungsabrechnung. Die Organisation benennt ihre konkrete Grundlage nach Art. 6 DSGVO und bei Gesundheitsdaten zusätzlich Art. 9 Abs. 2 DSGVO.'],
    ['Wer Daten erhalten kann','Berechtigte Mitarbeitende erhalten aufgabenbezogene Einsicht. Kostenträger, verordnende Personen, Vertretungen und andere Stellen erhalten Daten nur auf geeigneter Rechtsgrundlage und im erforderlichen Umfang. CareSuite ist für die technische Auftragsverarbeitung vorgesehen. Aktive technische Dienste und internationale Übermittlungen werden in der ausgehändigten Anlage erläutert.'],
    ['Portal Dateien und Bestätigungen','Das Klientenportal zeigt nur zugeordnete, freigegebene Inhalte. Fotos und zusätzliche Kommunikation werden zweckbezogen geprüft; freiwillige Erklärungen erfolgen getrennt. '+signatures],
    ['Fristen Rechte und Kontakt',retention+' '+rights+' Datenschutzkontakt der betreuenden Organisation und ergänzende Empfängerinformationen sind vor Aushändigung vollständig einzutragen.']);
  if(category === 'vollmachten' && /Kommunikationsvereinbarung/.test(title)) return S(
    ['Zugelassene Kommunikationswege','Für freigegebene digitale Kommunikation kann das persönliche CareSuite-Klientenportal genutzt werden. E-Mail, Messenger und andere Dienste werden einzeln benannt und auf Eignung für die betreffende Datenart geprüft. Die Existenz eines Kommunikationswegs erlaubt keinen ungeschützten Versand von Gesundheitsdaten.'],
    ['Identität Umfang und Kontakt','Empfangende Person, Vertretungsbefugnis, gewünschter Kanal und zugelassene Inhalte werden konkret festgelegt. Portalzugänge sind persönlich zu schützen. Fachliche Antworten erfolgen über die zuständige Organisation; CareSuite-Support betrifft technische Fragen.'],
    ['Dringlichkeit und Wechsel','Das Portal ist kein dauerhaft überwachter Notrufkanal. Dringende oder medizinische Notfälle werden über die geeigneten betrieblichen Kontakte beziehungsweise den Notruf gemeldet. Änderungen, Widerruf freiwilliger Kommunikation und falsche Empfängerzuordnung werden unverzüglich umgesetzt.']);
  if(category === 'personal' && /Verpflichtung auf Vertraulichkeit/.test(title)) return S(
    ['CareSuite-Zugriff und Verschwiegenheit',access+' Konten werden persönlich verwendet. Private Einsicht, Screenshots, Kopien und Weitergabe von Gesundheits- oder Personaldaten ohne dienstlichen Zweck sind unzulässig. Die Verpflichtung gilt auch nach Ende der Tätigkeit.'],
    ['Gerät Dokumentation und Vorfall',security+' '+incident],
    ['Information und gesetzliche Rechte','Die beschäftigte Person erhält getrennte Nutzungsregeln und Datenschutzinformationen. Diese Verpflichtung ist keine pauschale Einwilligung in Standortaufzeichnung oder Verhaltenskontrolle. Gesetzliche Auskunfts-, Beschwerde- und zulässige Hinweisgeberrechte bleiben gewahrt.']);
  if(category === 'personal' && /Einarbeitung|Fortbildungs|Austritts/.test(title)) return [section('cs_training','CareSuite-Unterweisung und Zugänge','Unterweisung umfasst persönlichen Zugang, Rollen und richtige Aktenzuordnung, sichere mobile Nutzung, tatsächliche Zeit- und Leistungseinträge, erforderliche Geräterechtfreigaben und Vorfallmeldung. Praktische Übungen und offene Fragen werden nachgewiesen. Bei Austritt werden Konten, Vertretungen, Geräte und Integrationen kontrolliert behandelt; aufbewahrungspflichtige Akten werden nicht allein wegen des Austritts gelöscht.')];
  if(category === 'qm' && /Dokumentenlenkung|Arbeitsanweisungen|Betriebsausfall/.test(title)) return [section('cs_process','CareSuite-Verfahren und Nachweis','Der zentrale Office-Katalog dient als gemeinsame Vorlagenquelle der Module. Vorlage, konkrete Dokumentfassung und Datei-Prüfwert werden auseinandergehalten. Freigabe, Ausgabe, Zuordnung, Nachfolgefassung und lokale Änderungen erhalten einen geregelten Ablauf. Die neue geschützte Datenbankablage ist bis zum tatsächlichen Betriebsnachweis als noch zu aktivieren zu kennzeichnen. Bei Ausfall werden vereinbarte Ersatznachweise später kontrolliert zusammengeführt.')];
  if(layout === 'contract' && !/SEPA|Abtretung|Vollmacht|Schlüssel/.test(title)) {
    if(/Einwilligung|Schweigepflichtentbindung/.test(title)) return [section('cs_consent','CareSuite-Verarbeitung und konkrete Auswahl','Die betreuende Organisation verwendet CareSuite HealthOS zur technischen Organisation und Dokumentation. '+roles+' Diese Erklärung benennt den tatsächlichen zusätzlichen Zweck, die betroffenen Daten, Empfänger, Dauer und die gewählte Entscheidung getrennt. Eine Einwilligung zur Foto- oder Videodokumentation gestattet keine Veröffentlichung. Eine Veröffentlichung benennt zusätzlich Medium, Empfängerkreis und Reichweite. Weder ein Portalzugang noch eine Geräteberechtigung ersetzt diese konkrete Erklärung.')];
    return [section('cs_contract','Ergänzende Vereinbarung zur digitalen Dokumentation',system+' '+roles+' Die vereinbarten Versorgungs- oder Beschäftigungsleistungen bleiben Leistungen der im Dokument bezeichneten Organisation. Erforderliche Nachweise und freigegebene Stammdaten können in CareSuite verarbeitet werden; tatsächliche Leistungen und Korrekturen bleiben nachvollziehbar. '+signatures+' Freiwillige Bildveröffentlichung, zusätzliche Kommunikationswege und besondere Standortverfahren werden gesondert geregelt. Die Software-Nutzung begründet für Klienten keine eigene Softwaregebühr und für Beschäftigte keine pauschale Pflicht zur Verwendung eines privaten Geräts.')];
  }
  return [];
}
